(process.argv.includes('--baseline-only')?baselineCase():process.argv.includes('--panel-only')?panelCase():(process.argv.includes('--immersive-only')||process.argv.includes('--weather-schedule-only'))?immersiveCase():fullCase()).catch(e=>{console.error(e);process.exitCode=1;});
